        return hod in end
    if hod >= max(end):
        return False
    moves = [
        g(a + 1, b, hod + 1, end),
        g(a, b + 1, hod + 1, end),
        g(a * 3, b, hod + 1, end),
        g(a, b * 3, hod + 1, end)
    ]
    return any(moves) if ((hod + 1) % 2) == (end[0] % 2) else all(moves)


